  get(target, prop) {
    if (prop === "invoke") {
      return async (...args) => {
        const result = await target.invoke(...args);
        const lastAi = result.filter(m => m._getType() === "ai").pop();
        if (lastAi?.usage_metadata) {
          tracker.record(nodeName, lastAi.usage_metadata);
          emit("tokenUsage", { nodeId: nodeName, ...lastAi.usage_metadata });
