// convertToBaseMessage hierarchy
function convertToBaseMessage(msg) {
  if (typeof msg === "string") {
    if (msg.startsWith("assistant:")) return new AIMessage(msg.slice(12));
    return new HumanMessage(msg);
  }
  if (msg instanceof BaseMessage) return msg;
  if (msg.type === "human") return new HumanMessage(msg.content);
  if (msg.type === "ai") return new AIMessage(msg.content);
  if (msg.type === "tool") return new ToolMessage(msg.content);
  return new HumanMessage(String(msg)); // fallback
}
